source_wording_tex:
\label{def:closure-deficit}
Given a packaging $\Pi : \mathcal{X}\to\mathcal{Y}$ and a staging scale $\tau$, the \emph{micro-closure deficit} is
\begin{equation}
\mathsf{CD}_\tau(\Pi)
:=
I(X_t; Y_{t+\tau} \mid Y_t).
\label{eq:closure-deficit}
\end{equation}

expanded_source_wording_tex:
\label{def:closure-deficit}
Given a packaging $\Pi : \mathcal{X}\to\mathcal{Y}$ and a staging scale $\tau$, the \emph{micro-closure deficit} is
\begin{equation}
\mathsf{CD}_\tau(\Pi)
:=
I(X_t; Y_{t+\tau} \mid Y_t).
\label{eq:closure-deficit}
\end{equation}

source_wording_tex:
\label{prop:cd-decomposition}
Under the stationary law of $(X_t,Y_t,Y_{t+\tau})$,
\begin{equation}
H(Y_{t+\tau}\mid Y_t)
=
H(Y_{t+\tau}\mid X_t)
+
\mathsf{CD}_\tau(\Pi).
\label{eq:cd-decomposition}
\end{equation}

expanded_source_wording_tex:
\label{prop:cd-decomposition}
Under the stationary law of $(X_t,Y_t,Y_{t+\tau})$,
\begin{equation}
H(Y_{t+\tau}\mid Y_t)
=
H(Y_{t+\tau}\mid X_t)
+
\mathsf{CD}_\tau(\Pi).
\label{eq:cd-decomposition}
\end{equation}

source_wording_tex:
\label{prop:cd-kl}
The micro-closure deficit can be written as
\begin{equation}
\mathsf{CD}_\tau(\Pi)
=
\sum_{x \in \mathcal{X}}
\pi(x)\,
D_{\mathrm{KL}}\!\bigl(
p_x^{(\tau)}
\,\|\,
\bar p_{\Pi(x)}^{(\tau)}
\bigr),
\label{eq:cd-kl}
\end{equation}
where, in the finite case,
\[
D_{\mathrm{KL}}(p\|q) := \sum_{y' \in \mathcal{Y}} p(y') \log \frac{p(y')}{q(y')},
\]
with the convention $0 \log (0/q)=0$.

