\end{theorem}

source_wording_tex:
\label{def:phi}
Let $\Phi:\N\to\R$ be a nonnegative sequence. We say $\Phi$ is an \emph{increment certificate}
for $t$ if for all $n$,
\[
\Phi(n)\ \le\ t(n+1)-t(n).
\]

expanded_source_wording_tex:
\label{def:phi}
Let $\Phi:\mathbb{N}\to\mathbb{R}$ be a nonnegative sequence. We say $\Phi$ is an \emph{increment certificate}
for $t$ if for all $n$,
\[
\Phi(n)\ \le\ t(n+1)-t(n).
\]

source_wording_tex:
\label{thm:workcap-no-zeno}
Assume the WORK$\times$CAP inequality and DIV from Definition~\ref{def:work-cap-div}.
Then $t$ has no finite upper bound, hence no Zeno cascade occurs.

