\toprule
\multicolumn{5}{@{}l}{\textit{Closure and audit metrics}} \\
\midrule
{View} & {States} & {Defect} & {RM} & {EPR} \\
\midrule
CNOT micro & 12 & 0 & 0 & \(2.72\times 10^{-17}\) \\
CNOT macro & 4 & \(3.47\times 10^{-18}\) & \(1.70\times 10^{-16}\) & 0 \\
XOR erased macro & 2 & 0.96 & 0.96 & 0 \\
\bottomrule
\end{tabularx}

